SELECT e.edge_id AS edgeId, e.from_node_id AS fromNodeId, e.to_node_id AS toNodeId, e.relation_type AS relationType, e.score AS score, e.properties_json AS propertiesJson FROM oag_graph_edges e JOIN oag_graph_nodes fn ON fn.domain = e.domain AND fn.node_id = e.from_node_id AND fn.enabled = 1 JOIN oag_graph_nodes tn ON tn.domain = e.domain AND tn.node_id = e.to_node_id AND tn.enabled = 1 WHERE e.domain = #{domain} AND e.enabled = 1 AND ( e.from_node_id IN
#{nodeId}
OR e.to_node_id IN
#{nodeId}
) ORDER BY e.score DESC, e.edge_id ASC LIMIT #{topK}
